'use client';
const React = require('react');
if (!React.useActionState) {
  React.useActionState = function(fn, init) { return [init, fn, false]; };
}
function ContactForm(props) {
  const [state, formAction] = React.useActionState(props.action, null);
  return { state, formAction };
}
module.exports = { ContactForm };

